const express = require('express');
const router = express.Router();
const pool = require('../db');
const bcrypt = require('bcrypt');

// Route for Registration
router.post('/register', async (req, res) => {
    const { fullName, email, password, studentId, className, isTeacher } = req.body;

    try {
        // Check if email already exists
        const userExists = await pool.query('SELECT * FROM users WHERE email = $1', [email]);
        if (userExists.rows.length > 0) {
            return res.status(400).json({ message: "Email already registered" });
        }

        // Hash password
        const hashedPassword = await bcrypt.hash(password, 10);

        // Insert new user
        const result = await pool.query(
            'INSERT INTO users (full_name, email, password, student_id, class_name, is_teacher) VALUES ($1, $2, $3, $4, $5, $6) RETURNING id, email',
            [fullName, email, hashedPassword, studentId, className, isTeacher]
        );

        res.status(201).json({ message: "Registration successful", userId: result.rows[0].id });
    } catch (err) {
        console.error(err.message);
        res.status(500).json({ message: "Server Error" });
    }
});

// Route for Login
router.post('/login', async (req, res) => {
    const { email, password } = req.body;

    try {
        // Search for user by email
        const userResult = await pool.query('SELECT * FROM users WHERE email = $1', [email]);
        
        if (userResult.rows.length === 0) {
            return res.status(401).json({ message: "Invalid email or password" });
        }

        const user = userResult.rows[0];

        // Compare hashed password
        const isMatch = await bcrypt.compare(password, user.password);
        
        if (!isMatch) {
            return res.status(401).json({ message: "Invalid email or password" });
        }

        res.status(200).json({ message: "Login successful", userId: user.id, email: user.email });
    } catch (err) {
        console.error(err.message);
        res.status(500).json({ message: "Server Error" });
    }
});

module.exports = router;